(function() {
  var SlackClient;

  SlackClient = require('slack-api-client');

  module.exports = function(grunt) {

    var sendMessage;
    sendMessage = function(options, cb) {
      var slack;
      slack = new SlackClient(options.token);
      grunt.log.writeln("Sending notification to " + options.channel + " Slack channel...");
      return slack.api.chat.postMessage({
        channel: options.channel,
        text: grunt.util.kindOf(options.text) === 'function' ? options.text(grunt, options) : options.text,
        username: options.username,
        as_user: options.as_user,
        parse: options.parse,
        link_names: options.link_names,
        attachments: grunt.util.kindOf(options.attachments) === 'array' ? JSON.stringify(options.attachments) : null,
        unfurl_links: options.unfurl_links,
        unfurl_media: options.unfurl_media,
        icon_url: options.icon_url,
        icon_emoji: options.icon_emoji
      }, function(err, res) {
        if (err) {
          grunt.fatal(err);
        }
        grunt.log.ok('Notification sent!');
        return cb();
      });
    };

    return grunt.registerMultiTask('slack_notifier', 'Send a message to a Slack channel', function() {
      var done, error, options;
      done = this.async();
      error = false;
      options = this.options({
        token: '',
        channel: '',
        text: '',
        username: 'Grunt.js'
      });
      if (!options.token) {
        error = true;
        grunt.log.error('Token is not set');
      }
      if (!options.channel) {
        error = true;
        grunt.log.error('Channel is not set');
      }
      if (!options.text) {
        error = true;
        grunt.log.error('Text is not set');
      }
      if (error) {
        grunt.log.error('Notification not sent!');
        return done();
      } else {
        return sendMessage(options, function() {
          return done();
        });
      }
    });
  };

}).call(this);

